// Web Worker that hosts a persistent Pyodide (Python-in-wasm) interpreter
// for src/lib/run/run-python.ts. Checked into git as a normal static asset
// (unlike the vendor-copied files under public/sandbox/pyodide/, which are
// gitignored and regenerated by scripts/copy-sandbox-assets.mjs).
//
// This is a real file served from an http(s): URL rather than a Blob-URL
// worker (`new Worker(URL.createObjectURL(blob))`) on purpose: `blob:` is a
// non-special URL scheme, so a worker created from one can't resolve
// root-relative importScripts()/fetch() paths like "/sandbox/pyodide/..."
// against it — that combination throws "The URL '...' is invalid" rather
// than 404ing, which is a much more confusing failure to debug. A static
// file has a normal http(s): base URL, so root-relative paths just work.
//
// Protocol (see run-python.ts for the main-thread side):
//   worker -> main : { type: "ready" }                  once Pyodide has loaded
//   worker -> main : { type: "load-error", message }     if loading Pyodide failed
//   main -> worker : { type: "run", code }                run one program
//   worker -> main : { type: "result", out, error }       captured stdout/stderr + whether it was an exception

self.pyodide = null;
self.__out = "";
const __write = (msg) => {
  self.__out += msg + "\n";
};

// Neuter every network/exfiltration path reachable from this worker's global scope,
// mirroring src/lib/run/run-js.ts's WORKER_SRC hardening for the JS sandbox. Pyodide
// bridges a `js` module into user Python (`import js`), so without this an untrusted
// script could do `import js; await js.fetch(url)` (or js.XMLHttpRequest / js.WebSocket
// / js.Worker / js.SharedWorker) and issue authenticated same-origin requests using the
// app's own cookies, or exfiltrate data outward via a nested worker or sendBeacon.
//
// Called ONCE, right after loadPyodide() resolves — loading Pyodide itself legitimately
// needs fetch (to pull the wasm/lockfile assets) and importScripts (the one call above,
// to load pyodide.js) — and BEFORE any user code ever runs. The invariant this protects:
// by the time runPythonAsync executes anything, self.fetch/js.fetch and friends are gone.
function neuterNetworkEgress() {
  self.fetch = () => { throw new Error("Network access is disabled in the sandbox."); };
  self.XMLHttpRequest = undefined;
  self.WebSocket = undefined;
  self.EventSource = undefined;
  self.importScripts = () => { throw new Error("importScripts disabled"); };
  self.Worker = undefined;
  self.SharedWorker = undefined;
  // `caches` is a getter-only accessor inherited from the WorkerGlobalScope prototype
  // chain (not an own, writable data property), so plain `self.caches = undefined`
  // silently no-ops (in non-strict-mode sloppy scripts, assigning through an inherited
  // accessor with no setter does not create a shadowing own property) — verified
  // against a real worker: after `self.caches = undefined`, `self.caches` still
  // resolves to the live CacheStorage object. Object.defineProperty shadows it with a
  // genuine own property instead, which does take effect.
  try {
    Object.defineProperty(self, "caches", { configurable: true, value: undefined });
  } catch (e) { /* best effort; fetch/XHR/WebSocket/Worker are already gone regardless */ }
  try {
    self.navigator.sendBeacon = () => { throw new Error("sendBeacon is disabled in the sandbox."); };
  } catch (e) {
    try {
      Object.defineProperty(self.navigator, "sendBeacon", {
        configurable: true,
        value: () => { throw new Error("sendBeacon is disabled in the sandbox."); },
      });
    } catch (e2) { /* nothing more we can do; fetch/XHR/WebSocket/Worker are already gone */ }
  }
}

(async () => {
  try {
    importScripts("/sandbox/pyodide/pyodide.js");
    self.pyodide = await self.loadPyodide({
      indexURL: "/sandbox/pyodide/",
      stdout: __write,
      stderr: __write,
    });
    neuterNetworkEgress();
    self.postMessage({ type: "ready" });
  } catch (err) {
    self.postMessage({ type: "load-error", message: (err && err.message) || String(err) });
  }
})();

self.onmessage = async (e) => {
  const msg = e.data;
  if (!msg || msg.type !== "run") return;
  if (!self.pyodide) {
    self.postMessage({ type: "result", out: "Python runtime not loaded.", error: true });
    return;
  }
  self.__out = "";
  // A fresh globals dict per run means top-level names from a previous run
  // never leak into the next one — the officially documented Pyodide
  // pattern for isolating executions in a long-lived interpreter.
  const namespace = self.pyodide.globals.get("dict")();
  try {
    await self.pyodide.runPythonAsync(msg.code, { globals: namespace });
    self.postMessage({ type: "result", out: self.__out, error: false });
  } catch (err) {
    self.__out += (err && err.message) || String(err);
    self.postMessage({ type: "result", out: self.__out, error: true });
  } finally {
    namespace.destroy();
  }
};
